/* @lc app=leetcode id=2440 lang=kotlin */ class Solution { fun componentValue(nums: IntArray, edges: Array<IntArray>): Int = nums.size.let { n -> Array(n) { ArrayList<Int>() }.also { g -> edges.forEach { (a, b) -> g[a].add(b).also { g[b].add(a) } } }.let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].filter { v -> par[v] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> nums.sum().let { tot -> (minOf(n, tot) downTo 1).filter { tot % it == 0 }.first { k -> (tot / k).let { t -> nums.copyOf().let { a -> order.all { v -> (a[v] <= t).also { ok -> if (ok && a[v] != t && v != 0) a[par[v]] += a[v] } } && a[0] == t } } }.let { it - 1 } } } } } } }